#pragma once
#include "g2_natural_driver.h"
// Original public-input routes combined in one process to reuse the loaded cumulative world.
struct RegionDriver:G2NaturalDriver{
 using G2NaturalDriver::G2NaturalDriver;
 void readyMagazine(int weapon){equip(weapon);if(game.session().magazine(weapon)>0){return;}need(game.session().hasReserve(),"Safe-room reload lacks actual reserve");press(InputAction::Weapon);for(int n=0;n<120;++n){tick();}press(InputAction::Attack);for(int n=0;n<400;++n){tick();}need(game.session().magazine(weapon)>0,"Safe-room public reload did not fill the actual magazine");lower();}
void hallStudy(){actAt({4,11},Direction::Left);actAt({5,5},Direction::Up);need(game.mapId()==128,"05 entry to upper corridor absent");actObject("m128-e3");need(game.mapId()==134,"05 to stair corridor absent");actObject("m134-e3");need(game.mapId()==135,"05 study absent");actObject("m135-e3");if(game.mapId()==135){actObject("m135-e3");}need(game.mapId()==140,"05 book room absent");}
 void studyHall(){actObject("m135-e7");actObject("m134-e2");actObject("m128-e7");actAt({23,8},Direction::Right);need(game.mapId()==132,"05 hall return absent");}
 void note(){upstairs();actAt({27,13},Direction::Right);actAt({22,10},Direction::Right);actAt({7,5},Direction::Up);need(game.mapId()==147,"05 natural note room absent");actObject("m147-e6");need(game.session().flag(492)&&game.session().count(189)==1&&!game.session().flag(435),"Natural note-first absent");actObject("m147-e2");actObject("m143-e5");walk({12,8});settle();need(game.mapId()==132,"05 note hall return absent");}
 void push(const std::string& id,Direction d){auto actor=findCharacter(game.world(),id);const Direction opposite=d==Direction::Up?Direction::Down:d==Direction::Right?Direction::Left:Direction::Right;walk(adjacentTile(actor.motion.tile(),opposite));int before=game.session().flag(432);InputFrame in;in.movement=d;tick(in);need(game.foreground()==ForegroundKind::Content,"Bookcase public contact not started");if(!before&&id.starts_with("m140-e2")&&d!=Direction::Up){need(!game.session().flag(432),"S432 committed before route barrier");}settle();for(int e=4;e<=27;++e){need(!findCharacter(game.world(),"m140-e"+std::to_string(e)).through,"Bookcase Through leaked");}}
 void books(bool right){push("m140-e4",Direction::Up);push("m140-e12",Direction::Up);for(int n=0;n<(right?4:2);++n){push(right?"m140-e20":"m140-e21",right?Direction::Right:Direction::Left);}need(game.session().flag(432),"Bookcase solved missing");actObject("m140-e28");need(game.session().flag(433)&&game.session().count(95)==1,"Natural05 I95 absent");actObject("m140-e2");need(game.mapId()==135&&!game.session().flag(430)&&!game.session().flag(431)&&!game.session().flag(432)&&game.session().flag(433),"Bookcase exit cleanup missing");}
 void clock(int hours,int minutes,int choice=0){item(96);need(game.mode()==ApplicationMode::Playing&&game.foreground()==ForegroundKind::Content,"Clock tool not submitted");int numeric=0,choiceFirst=0;std::uint64_t request=0,choiceRequest=0;for(int n=0;n<20000;++n){if(game.foreground()==ForegroundKind::None&&!game.dialogue().active()){return;}auto v=game.inputPromptView();InputFrame in=n%8==0?key():InputFrame{};if(v.cursor){const bool isNumber=v.lines.size()==1&&v.lines[0].size()==2&&v.lines[0][0]>=U'0'&&v.lines[0][0]<=U'9';if(isNumber){if(v.request!=request){request=v.request;++numeric;}const int desired=numeric==1?hours:minutes;const int column=v.cursor->column;const int digit=int(v.lines[0][column]-U'0'),target=column==0?desired/10:desired%10;if(digit!=target){in=key(InputAction::Up);}else if(column==1&&v.lines[0][0]-U'0'!=desired/10){in=key(InputAction::Left);}else{in=key();}}else{if(choiceRequest!=v.request){choiceRequest=v.request;choiceFirst=v.cursor->line;}in=key(v.cursor->line==choiceFirst+choice?InputAction::Confirm:InputAction::Down);}}tick(in);}throw std::runtime_error("05 clock stalled");}
 void hallMirror(){walk({10,7});settle();need(game.mapId()==133,"06 stairs missing");actAt({22,10},Direction::Right);need(game.mapId()==143,"06 corridor missing");actObject("m143-e6");need(game.mapId()==145,"06 mirror entry missing");walk({5,4});settle();move(Direction::Up);}
 void mirrorHall(){actObject("m145-e8");actObject("m143-e5");walk({12,8});settle();need(game.mapId()==132,"06 hall return missing");}
 void fire(){press(InputAction::Weapon);for(int n=0;n<120;++n){tick();}need(game.raised(),"06 raise failed");for(int attempt=0;attempt<2&&!game.session().flag(422);++attempt){const int before=game.session().magazine(game.session().equipped(1));press(InputAction::Attack);shots+=std::max(0,before-game.session().magazine(game.session().equipped(1)));for(int n=0;n<600;++n){tick();}}need(game.session().flag(422),"06 public attack did not break mirror");lower();}
 void investigateChoice(const std::string& id,int choice){auto a=findCharacter(game.world(),id);auto target=a.motion.tile();for(Direction side:{Direction::Down,Direction::Left,Direction::Right,Direction::Up}){auto from=adjacentTile(target,side);if(game.world().player().motion.tile()!=from&&!next(game.world(),from)){continue;}walk(from);move(side==Direction::Down?Direction::Up:side==Direction::Up?Direction::Down:side==Direction::Left?Direction::Right:Direction::Left);tick(key());choices(choice);return;}throw std::runtime_error("08 no service adjacency");}
 void unlock(TilePosition tile,Direction direction,int choice=0){walk(tile);move(direction);tick(key());choices(choice);}
 void hallBath(){actAt({19,14},Direction::Right);need(game.mapId()==136,"Natural09 inner entrance absent");actAt({22,4},Direction::Up);need(game.mapId()==148,"Natural09 water corridor absent");actAt({11,21},Direction::Up);need(game.mapId()==149,"Natural09 bathroom absent");}
 void bathHall(){actAt({9,11},Direction::Down);need(game.mapId()==148,"09 bathroom return absent");actAt({23,26},Direction::Down);need(game.mapId()==136,"09 water return absent");actAt({3,14},Direction::Left);need(game.mapId()==132,"09 hall return absent");}
 void hallKitchen(){actAt({4,11},Direction::Left);need(game.mapId()==129,"09 kitchen corridor absent");actAt({2,12},Direction::Left);need(game.mapId()==131,"09 kitchen absent");}
 void kitchenHall(){actAt({13,9},Direction::Right);actAt({23,8},Direction::Right);need(game.mapId()==132,"09 kitchen return absent");}
 void drain(int choice){walk({7,9});move(Direction::Up);tick(key());choices(choice);}
};
template<class Run>void regionStone(Run& run){
 run.walk({14,6});run.move(Direction::Right);need(findCharacter(run.game.world(),"m130-e5").motion.tile()==TilePosition{16,6}&&!run.game.session().flag(362),"First push failed");
 run.actAt({27,13},Direction::Right);need(run.game.mapId()==133,"Stone return failed");run.actAt({4,10},Direction::Left);need(findCharacter(run.game.world(),"m130-e5").motion.tile()==TilePosition{15,6},"Half push did not rebuild on re-entry");
 run.walk({14,6});for(int n=0;n<6;++n){run.move(Direction::Right);need(findCharacter(run.game.world(),"m130-e5").motion.tile()==TilePosition{16+n,6}&&!run.game.session().flag(362),"Six ordinary pushes failed");}
 run.walk({21,5});InputFrame fall;fall.movement=Direction::Down;run.tick(fall);bool targetBeforeCommit=false;for(int n=0;n<1000&&!run.game.session().flag(362);++n){const auto actor=findCharacter(run.game.world(),"m130-e5");if(actor.motion.tile()==TilePosition{21,10}&&actor.motion.moving()){targetBeforeCommit=true;need(!run.game.session().flag(362),"Fell fact committed at destination early");}run.tick();}
 need(targetBeforeCommit&&run.game.session().flag(362),"Stone route did not commit after physical route completion");run.settle();need(findCharacter(run.game.world(),"m130-e5").layer==0,"Fallen page missing");
 run.actAt({27,13},Direction::Right);run.walk({12,8});run.settle();need(run.game.mapId()==132,"Hall return failed");run.actAt({5,11},Direction::Left);need(run.game.mapId()==129,"Dining return failed");
 need(findCharacter(run.game.world(),"m129-e15").motion.tile()==TilePosition{19,5},"Original key placement missing");run.actAt({20,5},Direction::Left);need(run.game.session().flag(363)&&run.game.session().count(93)==1,"Key pickup missing");run.tick(key());run.settle();need(run.game.session().count(93)==1,"Repeat pickup duplicated key");
 run.actAt({22,8},Direction::Right);need(run.game.mapId()==132,"Dining to hall failed");run.upstairs();need(findCharacter(run.game.world(),"m130-e5").layer==0,"Fallen stone revived");run.actAt({5,5},Direction::Up);need(run.game.mapId()==139,"Wax corridor missing");
}
